230	    pub fn move_selection(&mut self, delta: i32) {
231	        let new_index = self.selected_index as i32 + delta;
232	        if new_index >= 0 && (new_index as usize) < self.step_templates.len() {
233	            self.selected_index = new_index as usize;
234	            self.ensure_visible();
235	        }
236	    }
237	
238	    /// Adjust scroll_offset to ensure selected_index is visible.
239	    fn ensure_visible(&mut self) {
240	        let visible = self.visible_count.get();
241	        if visible == 0 {
242	            return;
243	        }
244	
245	        // If selected is above visible area, scroll up
246	        if self.selected_index < self.scroll_offset {
247	            self.scroll_offset = self.selected_index;
248	        }
249	
250	        // If selected is below visible area, scroll down
251	        let last_visible = self.scroll_offset + visible.saturating_sub(1);
252	        if self.selected_index > last_visible {
253	            self.scroll_offset = self.selected_index.saturating_sub(visible - 1);
254	        }
255	    }
