        _ => Ok(TelemetryConsent::NoThanks),
    }
}

/// Get the failure reports directory path.
pub fn reports_dir() -> PathBuf {
    crate::sys::home_dir()
        .unwrap_or_else(|| PathBuf::from("~"))
        .join(".bivvy")
        .join("failure-reports")
}

