246	                    hint,
247	                    &resolutions,
248	                    diagnostic_funnel,
249	                    &mut fix_history,
250	                    &mut retry_count,
251	                    &mut skipped_by_user,
252	                    &mut aborted,
253	                    &mut final_result,
254	                    project_root,
255	                    base_env,
256	                    process_env,
257	                    ui,
