0	//! Process group / job control regression tests.
1	//!
2	//! These tests verify that bivvy survives running under a real
3	//! job-controlling shell (zsh with `MONITOR` option). The existing PTY
4	//! tests spawn bivvy directly — the expectrl PTY *is* the controlling
5	//! terminal, so there's no parent shell doing process group management.
6	//! That topology can't surface the bug where zsh reclaims the foreground
7	//! group after a child process exits, causing SIGTTOU/SIGTTIN or
8	//! premature suspension.
9	//!
10	//! These tests spawn **zsh** inside the PTY, then run bivvy as a
11	//! command within that zsh session. This gives us:
12	//!   - Real job control (zsh's `MONITOR` option)
13	//!   - Real process group assignment and foreground management
14	//!   - Real signal delivery (SIGTTOU, SIGTTIN, SIGTSTP)
15	//!   - A parent shell that actively manages the terminal foreground
16	//!
17	//! The critical transition under test: after a child process (step
18	//! command) exits, bivvy must reclaim the terminal foreground to
19	//! render the next interactive prompt. If process group isolation or
20	//! foreground reclamation is broken, the prompt never appears and
21	//! the test times out — or zsh reports "suspended (tty output)".
22	#![cfg(unix)]
23	
24	use assert_cmd::cargo::cargo_bin;
25	use expectrl::Session;
26	use std::fs;
27	use std::process::Command;
28	use std::time::Duration;
29	use tempfile::TempDir;
30	
31	const TIMEOUT: Duration = Duration::from_secs(60);
32	
33	/// Marker printed by .zshrc to confirm the shell is ready.
34	const READY: &str = "ZSH_READY";
35	
36	// ── ANSI stripping ──────────────────────────────────────────────────
37	
38	/// Strip ANSI escape sequences from PTY output for readable snapshots.
39	///
40	/// Handles:
41	///   - CSI sequences: `ESC [ <params> <final>`
42	///   - OSC sequences: `ESC ] ... BEL` or `ESC ] ... ESC \`
43	///   - SS2/SS3:       `ESC N <char>` / `ESC O <char>`
44	///   - Two-byte:      `ESC <letter>` (e.g. `ESC =`, `ESC >`)
45	fn strip_ansi(s: &str) -> String {
46	    let mut result = String::with_capacity(s.len());
47	    let mut chars = s.chars().peekable();
48	
49	    while let Some(c) = chars.next() {
50	        if c == '\x1b' {
51	            match chars.peek() {
52	                // CSI: ESC [ <params> <final byte 0x40-0x7E>
53	                Some('[') => {
54	                    chars.next(); // consume '['
55	                    for ch in chars.by_ref() {
56	                        if ch.is_ascii() && (0x40..=0x7E).contains(&(ch as u8)) {
57	                            break;
58	                        }
