88	    fn show_hint(&mut self, hint: &str) {
89	        if self.mode.shows_status() {
90	            self.println(&self.theme.hint.apply_to(hint).to_string());
91	            self.println("");
92	        }
93	    }
94	
95	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
96	        let b = &self.theme.border;
97	        let pad = " ".repeat(indent);
98	        let mut lines = vec![
99	            format!(
100	                "{}{} {}",
101	                pad,
102	                b.apply_to("┌─"),
103	                b.apply_to("Command ──────────────────────────")
104	            ),
105	            format!(
106	                "{}{} {}",
107	                pad,
108	                b.apply_to("│"),
109	                self.theme.command.apply_to(command)
110	            ),
111	        ];
112	
113	        if !output.is_empty() {
114	            lines.push(format!(
115	                "{}{} {}",
116	                pad,
117	                b.apply_to("├─"),
118	                b.apply_to("Output ───────────────────────────")
119	            ));
120	            for line in output.lines() {
121	                lines.push(format!("{}{} {}", pad, b.apply_to("│"), line));
122	            }
123	        }
124	
125	        lines.push(format!(
126	            "{}{}",
127	            pad,
128	            b.apply_to("└────────────────────────────────────")
129	        ));
130	
131	        if let Some(h) = hint {
132	            lines.push(String::new());
133	            lines.push(format!(
134	                "{}{} {}",
135	                pad,
136	                self.theme.hint.apply_to("Hint:"),
137	                self.theme.hint.apply_to(h)
138	            ));
139	        }
140	
141	        for line in &lines {
142	            self.println(line);
143	        }
144	    }
145	}
