//! Interactive prompts.

use console::{style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Check if a key is Ctrl+D (EOF signal).
fn is_ctrl_d(key: &Key) -> bool {
    matches!(key, Key::Char('\x04'))
}

/// Check if an IO error represents EOF (triggered by Ctrl+D in cooked mode).
fn is_eof_error(e: &std::io::Error) -> bool {
    e.kind() == std::io::ErrorKind::UnexpectedEof
}

/// Check if a dialoguer error represents EOF.
fn is_dialoguer_eof(e: &dialoguer::Error) -> bool {
    match e {
        dialoguer::Error::IO(io_err) => io_err.kind() == std::io::ErrorKind::UnexpectedEof,
    }

